do $$declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();foreign_account uuid:=gen_random_uuid();r jsonb;blocked boolean;memory jsonb:='{"title":"Routine haircut preference","guidance":"Treat routine haircuts as Personal Care; ask about unusual services.","effect":"guidance","module":"all","merchant":"Salon","category":"","account_id":null,"currency":"USD","min_amount":0,"max_amount":200,"starts_on":"2026-11-25","ends_on":null,"enabled":true}';begin
 insert into auth.users values(u),(v);insert into accounts(id,user_id,name) values(foreign_account,v,'Other owner');
 insert into finance_assistant_items(id,owner_id,module,task,kind,payload,status) values(a,u,'transactions','categories','question','{"question":"First purchase?"}','needs_input'),(b,u,'transactions','categories','question','{"question":"Second purchase?"}','needs_input');
 perform set_config('request.jwt.claim.sub',u::text,true);
 blocked:=false;begin perform finance_answer_and_remember(jsonb_build_array(jsonb_build_object('id',a,'revision',1)),'Haircut',memory||jsonb_build_object('account_id',foreign_account));exception when raise_exception then blocked:=true;end;
 if not blocked or exists(select 1 from finance_assistant_items where answer<>'') or exists(select 1 from finance_learning_policies) then raise exception 'Invalid future scope partially saved an answer or policy';end if;
 blocked:=false;begin perform finance_answer_and_remember(jsonb_build_array(jsonb_build_object('id',a,'revision',1)),'Haircut',memory||'{"effect":"expense_now"}');exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Answer memory expanded automatic financial permissions';end if;
 r:=finance_answer_and_remember(jsonb_build_array(jsonb_build_object('id',a,'revision',1),jsonb_build_object('id',b,'revision',1)),'Haircut',memory);
 if r->>'policyId' is null or (r->>'answered')::integer<>2 or r->'item'->>'answer'<>'Haircut' then raise exception 'Answer and policy result missing';end if;
 if (select count(*) from finance_learning_policies where owner_id=u and source_item_id=a and guidance=memory->>'guidance' and starts_on='2026-11-25' and max_amount=200)<>1 or (select revision from finance_learning_state where owner_id=u)<>1 or (select count(*) from finance_learning_history where owner_id=u)<>1 then raise exception 'Remembered scope, source or audit missing';end if;
 blocked:=false;begin perform finance_answer_and_remember(jsonb_build_array(jsonb_build_object('id',a,'revision',1)),'Replay',memory);exception when raise_exception then blocked:=true;end;if not blocked or (select count(*) from finance_learning_policies)<>1 then raise exception 'Retry duplicated memory';end if;
 perform set_config('request.jwt.claim.sub',v::text,true);blocked:=false;begin perform finance_answer_and_remember(jsonb_build_array(jsonb_build_object('id',a,'revision',2)),'Other owner',memory);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Foreign answer accepted';end if;
 if has_function_privilege('anon','finance_answer_and_remember(jsonb,text,jsonb)','EXECUTE') then raise exception 'Anonymous memory access';end if;
end;$$;
rollback;
